export const BRUTO: Bruto[] = [
  [1, "", 1, "pt", "Reescrita de frases", [0, 1], "Com correção gramatical, o período “A rigor (...) histórico” (ℓ.10-11) poderia, sem se contrariar a ideia original do texto, ser assim reescrito: Caso se proceda com rigor, a análise desses conceitos, verifica-se que não existe diferenças entre eles.", "E", "A reescrita tem erros: falta a crase em “proceda (...) à análise” (o verbo pede a preposição “a”), a vírgula separa termos ligados, e “existir” devia concordar com “diferenças” (não existem diferenças). A correção não se mantém.", ""],
  [2, "", 1, "pt", "Compreensão e interpretação de textos", [0, 1], "A informação que inicia o texto é suficiente para se inferir que Freud conheceu a obra de Marx, mas o contrário não é verdadeiro, visto que esses pensadores não foram contemporâneos.", "E", "O texto diz só que Marx teria descoberto o inconsciente três décadas antes de Freud. Isso não basta para concluir que Freud conheceu a obra de Marx nem que os dois não foram contemporâneos.", ""],
  [3, "", 1, "pt", "Coesão e referenciação", [0, 1], "A expressão “dessas duas palavras” (ℓ.11), como comprovam as ideias desenvolvidas no parágrafo em que ela ocorre, remete não aos dois vocábulos que imediatamente a precedem — “mais-valia” (ℓ.8) e “inconsciente” (ℓ.9) —, mas, sim, a “fetichismo” (ℓ.7) e “alienação” (ℓ.8).", "C", "“Dessas duas palavras” retoma os dois conceitos do primeiro parágrafo, “fetichismo” e “alienação”, que o parágrafo seguinte compara em Freud e em Marx. Não retoma “mais-valia” e “inconsciente”.", ""],
  [4, "", 1, "pt", "Compreensão e interpretação de textos", [0, 1], "Depreende-se da argumentação apresentada que a autora do texto, ao aproximar conceitos presentes nos estudos de Marx e de Freud, busca demonstrar que, nas sociedades “de mercado”, a “divisão do sujeito” (ℓ.14) se processa de forma análoga na subjetividade dos indivíduos e na relação de trabalho.", "C", "A autora diz que o sujeito das duas teorias é um só: quem sofre de sintomas inconscientes é o mesmo que não percebe que o poder das mercadorias causa sua miséria. A divisão do sujeito aparece na subjetividade e na relação de trabalho, que gera a mais-valia.", ""],
  [5, "", 1, "pt", "Reescrita de frases", [2, 3], "Suprimindo-se o emprego de termos característicos da linguagem informal, como o da palavra “coisa” (ℓ.9) e o do trecho “(como você e eu)” (ℓ.10), o primeiro período do segundo parágrafo poderia ser reescrito, com correção gramatical, da seguinte forma: Essa prática social apresenta-se mais complexa na modernidade, onde a autoridade jurídica e moral submete-se à opinião pública.", "E", "“Onde” só se usa para lugar físico, e “modernidade” indica tempo. A reescrita também muda o sentido: o texto não fala em submissão à opinião pública, e sim em os cidadãos serem a fonte da autoridade.", ""],
  [6, "", 1, "pt", "Concordância", [2, 3], "No período “Nesse caso (...) estaria conosco” (ℓ.3-5), como o conector “ou” está empregado com sentido aditivo, e não, de exclusão, a forma verbal do predicado “seria simples” poderia, conforme faculta a prescrição gramatical, ter sido flexionada na terceira pessoa do plural: seriam.", "E", "O sujeito de “seria simples” é formado por orações (puxar a corda, afiar a faca ou assistir à execução). Com sujeito oracional, o verbo fica no singular; o plural “seriam” não cabe.", ""],
  [7, "", 1, "pt", "Compreensão e interpretação de textos", [2, 3], "De acordo com o texto, nas sociedades tradicionais, os cidadãos sentem-se aliviados sempre que um soberano decide infligir a pena de morte a um infrator porque se livram das ameaças de quem desrespeita a moral que rege o convívio social, como evidencia o emprego da interjeição “que alívio!” (ℓ.8).", "E", "O alívio vem de a coletividade não carregar a responsabilidade moral da execução, já que quem decide é o soberano. Não vem de ficar livre das ameaças do infrator.", ""],
  [8, "", 1, "pt", "Reescrita de frases", [2, 3], "Mantendo-se a correção gramatical e a coerência do texto, a oração “se alguém é executado” (ℓ.12), que expressa uma hipótese, poderia ser escrita como caso se execute alguém, mas não, como se caso alguém se execute.", "C", "“Caso se execute alguém” mantém a hipótese, com “caso” no lugar de “se” e a passiva sintética. Já “se caso alguém se execute” junta dois conectivos de mesma função e, com o sujeito antes do verbo, o “se” vira reflexivo (alguém executa a si mesmo): muda o sentido.", ""],
  [9, "", 1, "pt", "Coesão e referenciação", [2, 3], "O termo “Essa discrição” (ℓ.18) refere-se apenas ao que está expresso na primeira oração do período que o antecede.", "C", "“Essa discrição” retoma só o fato de as execuções acontecerem em lugares fechados, diante de poucas testemunhas. A oração seguinte (“há uma espécie de vergonha”) é uma avaliação e não é retomada.", ""],
  [10, "", 1, "pt", "Compreensão e interpretação de textos", [2, 3], "Na condição de psicanalista, o autor do texto adverte que a punição de infratores das leis é uma forma de os indivíduos expurgarem seus desejos inconfessáveis, ressalvando, no entanto, que, quando se trata de crime hediondo, tal não se aplica.", "E", "O autor só levanta a possibilidade (“é possível que haja”) de crimes hediondos em que não reconhecemos nossos desejos reprimidos. Não afirma que a ressalva vale para todo crime hediondo.", ""],
  [11, "", 1, "pt", "Crase", [2, 3], "Na linha 24, considerando-se a dupla regência do verbo impor e a presença do pronome “mesmas”, seria facultado o emprego do acento indicativo de crase na palavra “as” da expressão “as mesmas renúncias”.", "E", "Em “não se impõem as mesmas renúncias”, “se” é o objeto indireto (impõem a si) e “as mesmas renúncias” é o objeto direto. Não há preposição antes de “as”, por isso a crase não cabe.", ""],
  [12, "", 1, "pt", "Sintaxe", [4, 5], "Considerando-se as relações entre os termos da oração, verifica-se ambiguidade no emprego do adjetivo “pensativos” (v. 40), visto que ele pode referir-se tanto ao termo “vossos mortos” (v.38) quanto ao núcleo nominal “olhos” (v.40).", "C", "“Pensativos” pode ser predicativo de “vossos mortos” (os mortos, pensativos, abrem os olhos) ou adjunto de “olhos” (olhos pensativos). As duas leituras são possíveis: há ambiguidade.", ""],
  [13, "", 1, "pt", "Tempos e modos verbais", [4, 5], "No poema, que apresenta uma denúncia de atos de abuso de poder, foram utilizados os seguintes recursos que permitem que a poeta se dirija diretamente a um interlocutor: emprego de vocativo nos versos 1, 9 e 33 e de verbos na segunda pessoa do plural, todos no imperativo afirmativo.", "E", "Há vocativos nos versos 1, 9 e 33, mas nem todos os verbos na 2ª pessoa do plural estão no imperativo: “calculais” (v. 3), por exemplo, está no presente do indicativo.", ""],
  [14, "", 1, "pt", "Coesão e referenciação", [4, 5], "O emprego do pronome possessivo em “seus rutilantes vestidos” (v.12) evidencia que essa expressão corresponde à vestimenta usada por autoridades em eventos solenes.", "E", "“Seus” se refere a “pavões”: as personagens arrastam os apelidos como os pavões arrastam seus vestidos. Para as personagens, o poema usaria “vossos”. A expressão não descreve roupa de autoridades.", ""],
  [15, "", 1, "pt", "Concordância", [4, 5], "No verso 23, a forma verbal “nascidas”, apesar de referir-se a todas as expressões nominais que a antecedem, concorda apenas com a mais próxima, conforme faculta regra de concordância nominal.", "E", "Sem vírgula depois de “sepulturas”, “nascidas” se refere só a “profundas sepulturas”. Não se liga a todos os termos da enumeração, e não combinaria com “duro peso de algemas”.", ""],
  [16, "", 1, "pt", "Sintaxe", [4, 5], "Os trechos “Por sentenças, por decretos” (v.29) e “Por fictícia autoridade, vãs razões, falsos motivos” (v.35-36) exercem função adverbial nas orações a que pertencem e ambos denotam o meio empregado na ação representada pelo verbo a que se referem.", "E", "Os dois trechos são adjuntos adverbiais, mas só o primeiro indica meio (por sentenças, por decretos). O segundo indica causa: matastes por fictícia autoridade, vãs razões, falsos motivos.", ""],
  [17, "", 1, "pt", "Redação oficial", [6], "Cumpre destacar a necessidade de aumento do contingente policial e que é imperioso a ação desses indivíduos em âmbito nacional, pelo que a realização de concurso público para provimento de vagas no Departamento de Polícia Federal consiste em benefício a toda a sociedade.", "E", "Falta paralelismo: “necessidade” é completada por um nome (de aumento) e por uma oração (e que é imperioso...). E “imperioso” devia concordar com “a ação” (imperiosa).", ""],
  [18, "", 1, "pt", "Redação oficial", [6], "Caro Senhor Perito Criminal,\nConvidamos Vossa Senhoria a participar do evento “Destaques do ano”, em que será homenageado pelo belo e admirável trabalho realizado na Polícia Federal. Por gentileza, confirme sua presença a fim de que possamos providenciar as honrarias de praxe.", "E", "O texto não é impessoal: usa adjetivos de valor pessoal, como “caro”, “belo” e “admirável”.", "Depois da prova, o Decreto 9.758/2019 passou a usar só “senhor” (e não “Vossa Senhoria”) na comunicação com agentes públicos federais."],
  [19, "", 1, "pt", "Redação oficial", [6], "O departamento que planejará o treinamento de pessoal para a execução de investigações e de operações policiais, sob cuja responsabilidade está também a escolha do local do evento, não se manifestou até o momento.", "C", "O trecho é impessoal, claro, formal e correto. “Sob cuja responsabilidade” está bem empregado: a escolha do local está sob a responsabilidade do departamento.", ""],
  [20, "", 1, "pt", "Redação oficial", [6], "Senhor Delegado,\nSegue para divulgação os relatórios das investigações realizadas no órgão, a fim de fazer cumprir a lei vigente.", "E", "“Segue” devia concordar com “os relatórios” (seguem). E o fim da frase é ambíguo: não fica claro se é a divulgação ou as investigações que servem para cumprir a lei.", ""],
  [21, "", 1, "pt", "Redação oficial", [6], "Solicito a Vossa Senhoria a indicação de cinco agentes de polícia aptos a ministrar aulas de direção no curso de formação de agentes. O início do curso, que será realizado na capital federal, está previsto para o segundo semestre deste ano.", "C", "O trecho é claro, formal e correto. “Vossa Senhoria” não aceita artigo, por isso não há crase em “a Vossa Senhoria”, e o verbo na 1ª pessoa (solicito) só indica quem assina o pedido.", "Depois da prova, o Decreto 9.758/2019 passou a usar só “senhor” (e não “Vossa Senhoria”) na comunicação com agentes públicos federais."],
  [22, "", 1, "pt", "Redação oficial", [7], "A exposição de motivos de caráter meramente informativo deve apresentar, na introdução, no desenvolvimento e na conclusão, a sugestão de adoção de uma medida ou de edição de um ato normativo, além do problema inicial que justifique a proposta indicada.", "E", "A exposição de motivos só informativa não propõe medida nem ato normativo: apenas informa o Presidente da República sobre um assunto e segue o padrão ofício. Apontar problema, medida e solução é exigência da que propõe medida ou ato.", ""],
  [23, "", 1, "pt", "Redação oficial", [7], "A estrutura do telegrama e da mensagem por correio eletrônico de caráter oficial é flexível.", "C", "Pelo Manual (2ª ed.), não há forma rígida para o correio eletrônico, e o telegrama não tem padrão rígido (segue os formulários dos Correios). As duas estruturas são flexíveis.", "A 3ª edição do Manual (2018) não trata mais do telegrama; para o correio eletrônico continua valendo a forma flexível."],
  [24, "", 1, "pt", "Redação oficial", [7], "As comunicações oficiais emitidas pelo presidente da República, por chefes de poderes e por ministros de Estado devem apresentar ao final, além do nome da pessoa que as expede, o cargo ocupado por ela.", "E", "Só as comunicações assinadas pelo Presidente da República dispensam o nome e o cargo de quem as expede; as dos chefes de poderes e ministros trazem nome e cargo.", ""],
  [25, "", 1, "pt", "Redação oficial", [7], "O referido manual estabelece o emprego de dois fechos para comunicações oficiais: Respeitosamente, para autoridades superiores; e Atenciosamente, para autoridades de mesma hierarquia ou de hierarquia inferior. Tal regra, no entanto, não é aplicável a comunicações dirigidas a autoridades estrangeiras.", "C", "O Manual prevê só dois fechos: Respeitosamente (autoridades superiores) e Atenciosamente (mesma hierarquia ou inferior). As comunicações a autoridades estrangeiras ficam fora dessa regra e seguem rito próprio.", ""],
  [26, "", 1, "pt", "Redação oficial", [7], "A menos que o expediente seja de mero encaminhamento de documentos, o texto de comunicações como aviso, ofício e memorando, que seguem o padrão ofício, deve conter três partes: introdução, desenvolvimento e conclusão.", "C", "No padrão ofício, o texto tem introdução, desenvolvimento e conclusão, salvo quando é de mero encaminhamento de documentos, que tem estrutura própria.", "Na data da prova valia a 2ª edição do Manual de Redação da Presidência da República (2002). A 3ª edição (2018) acabou com a diferença entre ofício, aviso e memorando: hoje todos seguem o padrão ofício e se chamam ofício."],
  [27, "", 1, "info", "Redes de computadores", [8], "O uso de dispositivos bluetooth em portas USB necessita de driver especial do sistema operacional. Em termos de funcionalidade, esse driver equivale ao de uma interface de rede sem fio (wireless LAN), pois ambas as tecnologias trabalham com o mesmo tipo de endereço físico.", "E", "O adaptador Bluetooth costuma usar driver do fabricante, e Bluetooth e Wi-Fi são tecnologias diferentes, com alcance e velocidade bem diferentes. Não há a equivalência citada.", ""],
  [28, "", 1, "info", "Excel", [9], "Um usuário que deseje que todos os valores contidos nas células de B2 até B16 de uma planilha Excel sejam automaticamente formatados para o tipo número e o formato moeda (R$) pode fazê-lo mediante a seguinte sequência de ações: selecionar as células desejadas; clicar, na barra de ferramentas do Excel, a opção Formato de Número de Contabilização; e, por fim, selecionar a unidade monetária desejada.", "C", "Selecionar B2:B16 e usar o botão Formato de Número de Contabilização, escolhendo a moeda, formata as células como número com símbolo monetário.", ""],
  [29, "", 1, "info", "Excel", [9], "Em uma planilha Excel, para somar os valores contidos nas células de B2 até B16 e colocar o resultado na célula B17, é suficiente que o usuário digite, na célula B17, a fórmula =SOMA(B2:B16) e tecle Enter.", "C", "=SOMA(B2:B16) em B17, confirmada com Enter, soma os valores de B2 a B16 e mostra o resultado em B17.", ""],
  [30, "", 1, "info", "Windows", [10, 11], "Se o usuário clicar o botão Limpeza de Disco, todos os vírus de computador detectados no disco C serão removidos do sistema operacional.", "E", "A Limpeza de Disco apaga arquivos temporários e dispensáveis para liberar espaço. Não procura nem remove vírus; isso é tarefa do antivírus.", ""],
  [31, "", 1, "info", "Windows", [10, 11], "O sistema operacional em questão não pode ser o Windows 7 Professional, uma vez que o tipo do sistema de arquivo não é FAT32.", "E", "O Windows 7 Professional aceita NTFS e FAT32, e o NTFS é o indicado para ele. Um disco em NTFS não exclui o Windows 7.", ""],
  [32, "", 1, "info", "Navegadores", [12], "Se o certificado digital na conexão HTTPS for maior que 1.024 bits, o usuário deverá escolher o Mozilla Firefox ou o Internet Explorer, que suportariam a conexão, pois o Google Chrome trabalha somente com certificados de até 796 bits.", "E", "O Chrome aceita certificados de 1.024 bits ou mais, como os outros navegadores. Não existe o limite de 796 bits citado.", ""],
  [33, "", 1, "info", "Navegadores", [12], "O Google Chrome, o Mozilla Firefox e o Internet Explorer suportam o uso do protocolo HTTPS, que possibilita ao usuário uma conexão segura, mediante certificados digitais.", "C", "Os três navegadores aceitam HTTPS, que cifra a conexão com SSL/TLS; nessa negociação o servidor apresenta um certificado digital.", ""],
  [34, "", 1, "info", "Hardware", [13, 14], "A figura 2 ilustra um conector do tipo S-Vídeo, utilizado para ligar dispositivos de vídeo em computadores ou em outros equipamentos de vídeo.", "C", "O plugue redondo de 4 pinos da figura 2 é o S-Vídeo, usado para ligar dispositivos de vídeo a computadores e a outros equipamentos de vídeo.", ""],
  [36, "", 1, "info", "Segurança da informação", [15], "Quando a solicitação de conexão do tipo UDP na porta 21 for recebida por estação com firewall desligado, caberá ao sistema operacional habilitar o firewall, receber a conexão, processar a requisição e desligar o firewall. Esse procedimento é realizado porque a função do UDP na porta 21 é testar a conexão do firewall com a Internet.", "E", "O sistema não liga o firewall sozinho para testar conexão, e a porta 21 é a do FTP (sobre TCP). Não existe a função de teste citada.", ""],
  [37, "", 1, "info", "Segurança da informação", [15], "Se uma estação com firewall habilitado receber solicitação de conexão do tipo TCP, a conexão será automaticamente negada, porque, comumente, o protocolo TCP transporta vírus.", "E", "O firewall habilitado não bloqueia toda conexão TCP: segue as regras configuradas. E o TCP não transporta vírus por natureza; malware circula por TCP ou UDP.", ""],
  [38, "", 1, "info", "Windows", [16, 17], "Marcar a caixa da opção Oculto, em Atributos, tornará o arquivo em questão inacessível para softwares antivírus.", "E", "O atributo Oculto só esconde o arquivo na listagem padrão. O antivírus continua conseguindo acessá-lo e examiná-lo.", ""],
  [39, "", 1, "info", "Windows", [16, 17], "Caso deseje alterar o nome do arquivo em questão, o usuário deverá selecionar o nome do arquivo na caixa de texto, alterá-lo conforme desejado e clicar o botão OK.", "C", "Na guia Geral, o nome fica numa caixa de texto editável; basta alterá-lo e clicar OK para renomear o arquivo.", ""],
  [40, "", 1, "info", "Windows", [16, 17], "Ao clicar na guia Detalhes, o usuário visualizará a data de criação do arquivo e a data de sua última modificação.", "C", "A guia Detalhes mostra as propriedades do arquivo, entre elas as datas de criação e de modificação.", ""],
  [41, "", 1, "atualidades", "Economia mundial", [18, 19], "O domínio do conhecimento mostra-se fundamental para a produção de riquezas e, ao impulsionar constantes inovações tecnológicas, amplia a capacidade produtiva e ajuda a promover a ampliação dos mercados consumidores, em meio a um contexto de acirrada competição em escala global.", "C", "Na economia globalizada, conhecimento e inovação tecnológica aumentam a produtividade e abrem mercados, num ambiente de forte competição entre empresas e países.", ""],
  [42, "", 1, "atualidades", "Economia brasileira", [18, 19], "A fragilidade do sistema educacional brasileiro, realidade confirmada por sucessivos testes de avaliação interna e externa, impede que o país seja considerado emergente no cenário econômico mundial contemporâneo, apesar do reconhecimento geral de suas inegáveis potencialidades.", "E", "Apesar das falhas da educação, o Brasil era, na época, considerado um país emergente: fazia parte dos BRICS, ao lado de Rússia, Índia, China e África do Sul.", ""],
  [43, "", 1, "atualidades", "Economia brasileira", [18, 19], "Apesar da privatização ocorrida na área das telecomunicações e dos inegáveis avanços verificados no setor, o número de linhas de telefonia móvel no Brasil é insuficiente, se considerada a demanda apresentada pelo mercado consumidor brasileiro, e muito inferior ao de linhas fixas.", "E", "Depois da privatização, a telefonia móvel cresceu muito: em 2012 o Brasil já tinha mais linhas de celular do que habitantes, bem mais do que linhas fixas.", ""],
  [44, "", 1, "atualidades", "Economia mundial", [18, 19], "Tal como o Brasil, a China não possui tecnologia que lhe permita produzir semicondutores, uma das razões pelas quais sua atuação no mercado mundial, embora relativamente expressiva, está bem aquém do esperado, atrás de Índia e Rússia.", "E", "A China tem indústria eletrônica gigante, produz semicondutores e é uma das maiores economias e exportadoras do mundo, à frente de Índia e Rússia. Desde 2009 é a maior parceira comercial do Brasil.", ""],
  [45, "", 1, "atualidades", "Economia brasileira", [18, 19], "Embora ocupe uma posição pouco relevante na pauta das exportações do país, o agronegócio brasileiro demonstra tendência de crescimento, e seu bom desempenho reflete a influência positiva exercida no setor pela EMBRAPA, sinônimo de elevado padrão de pesquisa científica na agropecuária.", "E", "O agronegócio tem grande peso nas exportações brasileiras (soja, carnes, açúcar, café). A EMBRAPA é, de fato, referência em pesquisa agropecuária, mas o setor não tem posição pouco relevante na pauta.", ""],
  [46, "", 1, "atualidades", "Narcotráfico nas Américas", [20, 21], "A Colômbia, país que sediou a Cúpula das Américas em 2012, permanece em guerra civil, e o Estado vai sendo derrotado pelo conluio entre narcotraficantes, milícias e guerrilheiros das Forças Armadas Revolucionárias da Colômbia, as FARCs, cada vez mais poderosas.", "E", "Em 2012 a Colômbia vivia situação bem mais calma que nas décadas anteriores: as FARC estavam enfraquecidas pela ação do Estado, e no mesmo ano começaram as negociações de paz com o governo.", ""],
  [47, "", 1, "atualidades", "Narcotráfico nas Américas", [20, 21], "O montante de recursos movimentado pelo tráfico de drogas ilícitas em escala global faz dessa atividade um dos principais sustentáculos do crime organizado mundial e cria um poder econômico difícil de ser enfrentado por muitos Estados nacionais.", "C", "O tráfico movimenta somas enormes em todo o mundo. Isso sustenta o crime organizado e cria um poder econômico capaz de corromper e desafiar muitos Estados.", ""],
  [48, "", 1, "atualidades", "Narcotráfico nas Américas", [20, 21], "O governante citado no texto sugere que erradicar a produção, interditar o tráfico e criminalizar o consumo são decisões que, integrando a estratégia de guerra contra as drogas comandada por Washington, deram resultados pífios, razão pela qual o tema deveria ser discutido em profundidade na Cúpula das Américas.", "C", "O texto diz que o presidente da Guatemala quer discutir o tema porque a política atual, puramente repressiva, fracassou. Erradicar a produção, interditar o tráfico e criminalizar o consumo são os eixos dessa política, liderada pelos EUA.", ""],
  [49, "", 1, "atualidades", "Política de drogas", [20, 21], "Zedillo, do México, Gaviria, da Colômbia, e Fernando Henrique Cardoso, do Brasil, são ex-presidentes latino-americanos que se engajaram no exame do tema das drogas e assumem posição crítica em relação a uma política de combate às drogas que obtém parcos resultados e cujo custo em vidas humanas é altíssimo.", "C", "Ex-presidentes do México, da Colômbia e do Brasil integraram comissões sobre drogas e passaram a criticar a guerra às drogas, de resultados pobres e alto custo em vidas humanas.", ""],
  [50, "", 1, "rlm", "Negação de proposições", [22, 23], "A proposição correspondente à negação da premissa 2 é logicamente equivalente a “Como eu não sou traficante, não estou levando uma grande quantidade de droga ou não a escondi”.", "E", "A negação de “se p, então q” é “p e não q”: sou traficante e (não estou levando grande quantidade ou não a escondi). A frase do item é outra condicional, que parte de “não sou traficante”; não equivale à negação.", ""],
  [51, "", 1, "rlm", "Lógica proposicional", [22, 23], "Se a proposição “Eu não sou traficante” for verdadeira, então a premissa 2 será uma proposição verdadeira, independentemente dos valores lógicos das demais proposições que a compõem.", "C", "A premissa 2 é uma condicional cujo antecedente é “eu fosse traficante”. Se “não sou traficante” é verdade, o antecedente é falso, e a condicional é verdadeira, qualquer que seja o consequente.", ""],
  [52, "", 1, "rlm", "Lógica de argumentação", [22, 23], "Sob o ponto de vista lógico, a argumentação do jovem constitui argumentação válida.", "E", "Há um caso com premissas verdadeiras e conclusão falsa: o jovem não é traficante, é usuário e leva grande quantidade. As premissas 2 e 3 ficam verdadeiras (antecedentes falsos), a 1 também, e a conclusão (se leva grande quantidade, não é usuário) fica falsa. O argumento é inválido.", ""],
  [53, "", 1, "rlm", "Lógica proposicional", [22, 23], "Se P e Q representam, respectivamente, as proposições “Eu não sou traficante” e “Eu sou usuário”, então a premissa 1 estará corretamente representada por P∧Q.", "C", "A vírgula de “eu não sou traficante, eu sou usuário” tem valor de “e”: a premissa afirma as duas coisas ao mesmo tempo. Com P e Q como no item, ela é P∧Q.", ""],
  [54, "", 1, "rlm", "Análise combinatória", [24, 25], "Se todos os policiais em questão estiverem habilitados a dirigir, então, formadas as equipes, a quantidade de maneiras distintas de se organizar uma equipe dentro de um veículo com cinco lugares — motorista e mais quatro passageiros — será superior a 100.", "C", "Com todos habilitados, os cinco ocupam os cinco lugares de 5! = 120 maneiras, mais de 100.", ""],
  [55, "", 1, "rlm", "Análise combinatória", [24, 25], "Há mais de 50 maneiras diferentes de compor as referidas equipes.", "E", "Para a primeira equipe: 2 delegados × 2 peritos × 2 escrivães × C(4,2) = 6 pares de agentes = 48. A segunda equipe é formada por quem sobra. São 48 maneiras, menos de 50.", ""],
  [56, "", 1, "rlm", "Probabilidade", [24, 25], "Se cinco dos citados policiais forem escolhidos, aleatoriamente e independentemente dos cargos, então a probabilidade de que esses escolhidos constituam uma equipe com a exigência inicial será superior a 20%.", "E", "Há C(10,5) = 252 grupos de cinco, e 48 deles formam uma equipe válida (item anterior). A probabilidade é 48 ÷ 252 ≈ 19%, menor que 20%.", ""],
  [57, "", 1, "rlm", "Conjuntos", [26, 27], "Dez denúncias foram classificadas apenas como crime de tráfico de pessoas.", "C", "Das 100 denúncias, 60 são de pornografia infantil (30 delas também de tráfico) e 30 de nenhum dos crimes. Sobram 100 − 60 − 30 = 10 só de tráfico de pessoas.", ""],
  [58, "", 1, "rlm", "Conjuntos", [26, 27], "Os crimes de tráfico de pessoas foram mais denunciados que os de pornografia infantil.", "E", "Tráfico de pessoas: 30 (dos dois crimes) + 10 (só tráfico) = 40 denúncias. Pornografia infantil: 60. O tráfico foi menos denunciado.", ""],
  [59, "", 1, "admgeral", "Estrutura organizacional", [28], "Na estruturação do Departamento de Polícia Federal, composto de órgãos como as Diretorias Técnico-Científica, de Inteligência Policial, de Gestão de Pessoal e a de Administração e Logística Policial, entre outros, foi adotada a denominada departamentalização funcional.", "C", "As diretorias se dividem pela função que exercem (técnico-científica, inteligência, pessoal, logística). Agrupar órgãos por função é a departamentalização funcional.", ""],
  [61, "", 1, "admgeral", "Teorias da administração", [28], "Se adotar a abordagem burocrática, o gestor, com o objetivo de definir as futuras promoções na organização, avaliará seus subordinados considerando aspectos relacionados ao mérito.", "C", "No modelo burocrático, a promoção se baseia no mérito e na competência técnica, não em relações pessoais.", ""],
  [62, "", 1, "admgeral", "Evolução da administração pública", [28], "A criação do Departamento Administrativo do Serviço Público (DASP), que propiciou a efetiva implantação do modelo denominado administração pública gerencial, ocorreu no governo do presidente Juscelino Kubitschek.", "E", "O DASP foi criado em 1938, no governo Vargas, e marcou a implantação do modelo burocrático. A administração gerencial só veio com a reforma de 1995.", ""],
  [63, "", 1, "admgeral", "Planejamento", [28], "A matriz SWOT consiste em ferramenta típica de planejamento operacional.", "E", "A matriz SWOT cruza forças e fraquezas internas com oportunidades e ameaças do ambiente. É ferramenta do planejamento estratégico, não do operacional.", ""],
  [64, "", 1, "admgeral", "Restos a pagar", [29], "Ao fornecedor que deseje ver inscrito em restos a pagar os valores devidos pela administração pública na condição de despesa já processada será suficiente provar que foi realizado o pertinente empenho da despesa.", "E", "Restos a pagar processados são despesas empenhadas e já liquidadas. Só o empenho não basta: é preciso a liquidação, que comprova a entrega do bem ou do serviço (Lei 4.320/1964, arts. 36 e 63).", ""],
  [65, "", 1, "admgeral", "Conta Única do Tesouro", [29], "O gestor público que pretenda sacar recursos da Conta Única do Tesouro deverá realizá-lo por intermédio de ordem bancária, diretamente no SIAFI. Para a efetivação de pagamentos, esses recursos são disponibilizados no Banco do Brasil S.A.", "C", "Os saques da Conta Única são feitos por ordem bancária emitida no SIAFI, e os recursos ficam disponíveis no Banco do Brasil, agente financeiro do Tesouro, para os pagamentos.", ""],
  [66, "", 1, "admgeral", "Suprimento de fundos", [29], "Um servidor designado pelo ordenador de despesas poderá realizar, com suprimento de fundos, o pagamento de despesas do vice-presidente da República durante viagens nacionais.", "C", "As normas federais admitem pagar com suprimento de fundos, por servidor designado pelo ordenador de despesas, as despesas de viagem do Presidente e do Vice-Presidente da República.", ""],
  [67, "", 1, "admgeral", "Receita pública", [29], "A alienação de bem da administração pública não é classificada como receita efetiva.", "C", "A alienação de bens troca um bem por dinheiro: o patrimônio não aumenta. É receita não efetiva (por mutação patrimonial).", ""],
  [68, "", 1, "economia", "Política monetária", [30], "Uma política monetária restritiva só será eficaz mediante o controle da criação de moeda pelas autoridades monetárias.", "E", "Os bancos comerciais também criam moeda ao emprestar parte dos depósitos. A política restritiva atua também sobre eles, com compulsório, juros e operações de mercado aberto; não depende só da moeda emitida pela autoridade.", ""],
  [69, "", 1, "economia", "Política fiscal", [30], "Uma política fiscal que vise ao fomento do crescimento econômico e à geração de empregos deve contemplar medidas de redução dos gastos públicos e elevação da carga tributária.", "E", "Para estimular o crescimento e o emprego, a política fiscal expansionista aumenta os gastos públicos e reduz os tributos. O item descreve o contrário: uma política restritiva.", ""],
  [70, "", 1, "economia", "Contas públicas", [30], "As necessidades de financiamento do setor público, no conceito operacional, são calculadas acrescendo-se ao déficit primário os juros reais da dívida passada.", "C", "No conceito operacional, as necessidades de financiamento do setor público somam o déficit primário e os juros reais da dívida, sem a correção monetária.", ""],
  [71, "", 1, "economia", "Funções do governo", [30], "Os governos exercem função alocativa para corrigir a alocação de recursos utilizados na produção de bens geradores de externalidades negativas; na presença de externalidades positivas, a intervenção governamental é desnecessária.", "E", "Externalidades positivas também justificam a intervenção: sem ela, o mercado produz menos que o desejável (educação, vacinação). O governo atua nas duas situações.", ""],
  [72, "", 1, "economia", "Contas públicas", [31], "O financiamento do déficit público por meio da venda de títulos da dívida pública tende a gerar pressão inflacionária.", "E", "Vender títulos ao público usa dinheiro que já circula, sem criar moeda nova. A pressão inflacionária vem do financiamento por emissão de moeda.", ""],
  [73, "", 1, "economia", "Contas públicas", [31], "No final do século passado, apesar de o Brasil ter apresentado constantes superávits primários, ele não necessariamente pagou os juros da dívida pública acumulada em períodos anteriores.", "C", "No fim dos anos 1990, os juros da dívida superavam os superávits primários. O déficit nominal continuava e a dívida crescia: o superávit não bastava para pagar os juros.", ""],
  [74, "", 1, "economia", "Economia brasileira", [31], "A inflação de demanda resultante do aumento da renda dos cidadãos foi uma das principais causas do fracasso dos planos econômicos adotados no Brasil nos anos 80 do século XX.", "C", "Nos planos dos anos 1980, como o Cruzado, o congelamento de preços com reajustes salariais aumentou a renda e o consumo. A demanda aquecida gerou desabastecimento e a volta da inflação.", ""],
  [75, "", 1, "economia", "Contas públicas", [31], "O superávit primário de uma economia corresponde à poupança gerada pelo governo para o pagamento dos juros da dívida pública.", "C", "O superávit primário é a sobra das receitas sobre as despesas, sem contar os juros. É a poupança do governo usada para pagar os juros da dívida.", ""],
  [76, "", 1, "contab", "Fatos contábeis", [32, 33], "Os eventos II, IV e V são classificados como fatos mistos, pois, além de provocarem variações no saldo patrimonial, representam a transposição de valores entre os grupos de contas patrimoniais.", "E", "II (baixa de bem inservível) e IV (redução de crédito por variação monetária) são modificativos: só reduzem o patrimônio líquido. Só o V (pagamento com desconto) é misto: troca ativo por passivo e gera um ganho.", ""],
  [77, "", 1, "contab", "Fatos contábeis", [32, 33], "Os eventos I e III classificam-se como fatos permutativos e não afetam o saldo patrimonial da entidade.", "E", "I (compra de veículo à vista) é permutativo: troca caixa por veículo. Já III (apropriação da folha) é modificativo: gera despesa e reduz o patrimônio líquido.", ""],
  [78, "", 1, "contab", "Ativo intangível", [34], "O valor amortizável de ativo intangível com vida útil indefinida deverá ser amortizado de modo a refletir o padrão de consumo, pela entidade, dos benefícios econômicos futuros.", "E", "Pelo CPC 04, o intangível com vida útil indefinida não é amortizado: passa por teste de recuperabilidade. Só o de vida útil definida é amortizado.", ""],
  [79, "", 1, "contab", "Ativo intangível", [34], "Não deve ser reconhecido como ativo o ágio derivado da expectativa de rentabilidade futura (goodwill) gerado internamente.", "C", "O CPC 04 não permite reconhecer como ativo o ágio (goodwill) gerado internamente.", ""],
  [80, "", 1, "contab", "Princípios de contabilidade", [35], "Segundo o princípio da oportunidade, é necessário ponderar a relação entre a oportunidade e a confiabilidade da informação, pois a falta de integridade e tempestividade na produção e na divulgação da informação contábil pode ocasionar a perda de sua relevância.", "C", "Pelo princípio da oportunidade, a informação deve ser íntegra e divulgada a tempo; sem tempestividade, perde relevância. Por isso é preciso pesar oportunidade e confiabilidade.", ""],
  [81, "", 1, "contab", "Princípios de contabilidade", [35], "De acordo com o princípio do registro do valor original, a atualização monetária não representa nova avaliação, mesmo gerando o ajustamento dos valores originais para determinada data, mediante aplicação de indexadores e outros elementos aptos a traduzir a variação do poder aquisitivo da moeda.", "C", "Pelo princípio do registro pelo valor original, a atualização monetária não é nova avaliação: só ajusta os valores originais à variação do poder aquisitivo da moeda.", ""],
  [82, "", 1, "contab", "Provisões", [36], "As provisões retificadoras do ativo são constituídas debitando-se uma conta de despesa e creditando-se uma conta patrimonial que represente a respectiva provisão.", "C", "A provisão retificadora do ativo, como a de perdas com créditos, é lançada a débito de uma despesa e a crédito da conta de provisão, que reduz o ativo.", ""],
  [84, "", 1, "contab", "Regimes de caixa e de competência", [37, 38], "Na apuração do resultado do mês de abril de 2012, não se consideram, tanto no regime de caixa quanto no de competência, os eventos III e IV, os quais repercutem na apuração do resultado, respectivamente, dos meses de março e maio.", "E", "O evento III entra no resultado de abril pelo regime de caixa (o dinheiro entrou em abril), e o IV entra pelo de competência (o serviço foi prestado em abril). Não é verdade que nenhum dos dois regimes os considera.", ""],
  [85, "", 1, "contab", "Demonstração do resultado", [39, 40], "A demonstração do resultado do exercício apresentou prejuízo de R$ 11.000,00.", "E", "Só as receitas de serviços (34.000) e as despesas de aluguéis (8.000) e de água, luz e telefone (15.000) entram no resultado: 34.000 − 23.000 = lucro de 11.000, não prejuízo. O estoque de material de consumo é conta do ativo, não despesa.", ""],
  [87, "", 1, "penal", "Extraterritorialidade", [41], "Será submetido ao Código Penal brasileiro o agente, brasileiro ou não, que cometer, ainda que no estrangeiro, crime contra administração pública, estando a seu serviço, ou cometer crime contra o patrimônio ou a fé pública da União, de empresa pública ou de sociedade de economia mista. A circunstância de a conduta ser lícita no país onde foi praticada ou de se encontrar extinta a punibilidade será irrelevante para a responsabilização penal do agente no Brasil.", "C", "Os crimes contra a administração pública por quem está a seu serviço e contra o patrimônio ou a fé pública da União, de empresa pública ou de sociedade de economia mista são de extraterritorialidade incondicionada (CP, art. 7º, I, “b” e “c”). As condições do § 2º, como ser crime também no local e não estar extinta a punibilidade, não se aplicam.", ""],
  [88, "", 1, "penal", "Conflito aparente de normas", [41], "Conflitos aparentes de normas penais podem ser solucionados com base no princípio da consunção, ou absorção. De acordo com esse princípio, quando um crime constitui meio necessário ou fase normal de preparação ou execução de outro crime, aplica-se a norma mais abrangente. Por exemplo, no caso de cometimento do crime de falsificação de documento para a prática do crime de estelionato, sem mais potencialidade lesiva, este absorve aquele.", "C", "Pela Súmula 17 do STJ, quando o falso se esgota no estelionato, sem mais potencialidade lesiva, é por este absorvido. É a consunção: o crime-meio fica absorvido pelo crime-fim.", ""],
  [90, "", 1, "penal", "Concurso de pessoas", [41], "No que diz respeito ao concurso de pessoas, o sistema penal brasileiro adota a teoria monista, ou igualitária, mas de forma temperada, pois estabelece graus de participação do agente de acordo com a sua culpabilidade, inclusive em relação à autoria colateral ou acessória, configurada quando duas ou mais pessoas produzem um evento típico de modo independente uma das outras.", "E", "O CP adota a teoria monista temperada (art. 29). Mas na autoria colateral não há concurso de pessoas: falta o vínculo subjetivo entre os agentes, e cada um responde pelo que fez.", ""],
  [91, "", 1, "penal", "Lei penal no tempo", [41], "O fato de determinada conduta ser considerada crime somente se estiver como tal expressamente prevista em lei não impede, em decorrência do princípio da anterioridade, que sejam sancionadas condutas praticadas antes da vigência de norma excepcional ou temporária que as caracterize como crime.", "E", "Pela anterioridade, ninguém é punido por conduta praticada antes de a lei a definir como crime (CF, art. 5º, XXXIX; CP, art. 1º). Vale também para a lei excepcional ou temporária, que só alcança os fatos praticados durante sua vigência (CP, art. 3º).", ""],
  [92, "", 1, "penal", "Moeda falsa", [42], "Luiz, proprietário da mercearia Pague Menos, foi preso em flagrante por policiais militares logo após passar troco para cliente com cédulas falsas de moeda nacional de R$ 20,00 e R$ 10,00. Os policiais ainda apreenderam, no caixa da mercearia, 22 cédulas de R$ 20,00 e seis cédulas de R$ 10,00 falsas. Nessa situação, as ações praticadas por Luiz — guardar e introduzir em circulação moeda falsa — configuram crime único.", "C", "Guardar e introduzir em circulação estão no mesmo tipo (CP, art. 289, § 1º), que é de ação múltipla: praticar mais de uma dessas condutas no mesmo contexto configura crime único.", ""],
  [93, "", 1, "penal", "Estelionato e peculato", [42], "No curso de investigação policial para apurar a prática de estelionato contra banco público, foi constatado que um de seus empregados concorreu culposamente para que outrem praticasse a infração. Logo após a descoberta dos fatos, o empregado reparou integralmente o dano causado, restituindo os valores devidamente corrigidos e atualizados antes do encerramento do inquérito policial. Nessa situação, está extinta a punibilidade do agente.", "E", "O estelionato só tem forma dolosa, por isso não existe participação culposa nele. A reparação do dano como causa de extinção da punibilidade é regra do peculato culposo (CP, art. 312, § 3º), não do estelionato.", ""],
  [94, "", 1, "penal", "Resistência e desobediência", [42], "Pedro se opôs à execução de diligência policial cujo objetivo era investigá-lo e recusou-se a colaborar com os agentes que a realizaram, razão por que a diligência não pôde ser executada. Nessa situação, Pedro não pode ser responsabilizado criminalmente por não ter atendido às ordens policiais, uma vez que o sistema penal brasileiro não pune a resistência passiva, tampouco a caracteriza como delito de desobediência.", "C", "A resistência exige violência ou ameaça ao funcionário (CP, art. 329); a oposição só passiva não a configura. E recusar-se a colaborar com a própria investigação não é desobediência, pois ninguém é obrigado a produzir prova contra si.", ""],
  [95, "", 1, "penal", "Reingresso de estrangeiro expulso", [42], "Juan, cidadão espanhol, que havia sido expulso do Brasil após cumprimento de pena por tráfico internacional de drogas, retornou ao país, sem autorização de autoridade competente, para visitar sua companheira e seu filho, nascido no curso do cumprimento da pena. Nessa situação, para que o simples reingresso de Juan ao Brasil configurasse crime, seria necessário que ele praticasse nova infração, de natureza dolosa, em território nacional.", "E", "O crime do art. 338 do CP se consuma com o simples reingresso do estrangeiro expulso. Não é preciso praticar nova infração.", ""],
  [96, "", 1, "proc", "Perícias", [43], "De acordo com inovações na legislação específica, a perícia deverá ser realizada por apenas um perito oficial, portador de diploma de curso superior; contudo, caso não haja, na localidade, perito oficial, o exame poderá ser realizado por duas pessoas idôneas, portadoras de diploma de curso superior, preferencialmente na área específica. Nessa última hipótese, serão facultadas a participação das partes, com a formulação de quesitos, e a indicação de assistente técnico, que poderá apresentar pareceres, durante a investigação policial, em prazo máximo a ser fixado pela autoridade policial.", "E", "A primeira parte está certa (CPP, art. 159, caput e § 1º). Mas o assistente técnico só atua depois de admitido pelo juiz e após a conclusão dos exames e do laudo pelos peritos oficiais (§ 4º). Não atua durante a investigação policial, em prazo fixado pela autoridade policial.", ""],
  [97, "", 1, "proc", "Direitos do investigado", [43], "Como o sistema processual penal brasileiro assegura ao investigado o direito de não produzir provas contra si mesmo, a ele é conferida a faculdade de não participar de alguns atos investigativos, como, por exemplo, da reprodução simulada dos fatos e do procedimento de identificação datiloscópica e de reconhecimento, além do direito de não fornecer material para comparação em exame pericial.", "E", "O investigado pode se recusar a participar da reprodução simulada e a fornecer material para exame. Mas não pode se negar à identificação datiloscópica, quando cabível, nem ao reconhecimento de pessoa, em que tem papel passivo.", "Depois da prova, a Lei 12.654/2012 passou a permitir a coleta de material biológico para obter o perfil genético na identificação criminal, quando essencial às investigações e autorizada pelo juiz (Lei 12.037/2009, art. 5º, parágrafo único)."],
  [98, "", 1, "proc", "Ofendido", [43], "O sistema processual vigente prevê tratamento especial ao ofendido, especialmente no que se refere ao direito de ser ouvido em juízo e de ser comunicado dos atos processuais relativos ao ingresso e à saída do acusado da prisão, à designação de data para audiência e à sentença e respectivos acórdãos. Além disso, ao ofendido é conferido o direito da preservação da intimidade, da vida privada, da honra e da imagem, o que, entretanto, não obsta a acareação entre ele e o acusado.", "C", "O CPP garante ao ofendido ser comunicado do ingresso e da saída do acusado da prisão, das audiências e da sentença (art. 201, § 2º) e a preservação da intimidade, da vida privada, da honra e da imagem (§ 6º). A acareação entre ofendido e acusado continua possível (art. 229).", ""],
  [99, "", 1, "proc", "Inquérito policial", [43], "O Código de Processo Penal determina expressamente que o interrogatório do investigado seja o último ato da investigação criminal antes do relatório da autoridade policial, de modo que seja possível sanar eventuais vícios decorrentes dos elementos informativos colhidos até então bem como indicar outros elementos relevantes para o esclarecimento dos fatos.", "E", "O CPP não exige que o interrogatório do investigado seja o último ato do inquérito (art. 6º, V). Ser o último ato é regra da audiência no processo judicial (art. 400), depois da reforma de 2008.", ""],
  [101, "", 1, "proc", "Testemunhas", [44], "De acordo com o sistema processual penal brasileiro, qualquer pessoa poderá ser testemunha e a ninguém que tenha conhecimento dos fatos será dado o direito de se eximir da obrigação de depor, com exceção das pessoas proibidas de depor porque, em razão de função, ministério, ofício ou profissão, devam guardar segredo, salvo se desobrigadas pela parte interessada, e dos doentes e deficientes mentais e menores de quatorze anos de idade.", "E", "Doentes e deficientes mentais e menores de 14 anos não ficam dispensados de depor: só não prestam o compromisso de dizer a verdade (CPP, art. 208). E o item omite que parentes próximos do acusado podem se recusar a depor (art. 206).", ""],
  [102, "", 1, "proc", "Prisão em flagrante", [44], "Considere que, no curso de investigação policial para apurar a prática de crime de extorsão mediante sequestro contra um gerente do Banco X, agentes da Polícia Federal tenham perseguido os suspeitos, que fugiram com a vítima, por dois dias consecutivos. Nessa situação, enquanto mantiverem a privação da liberdade da vítima, os suspeitos poderão ser presos em flagrante, por se tratar de infração permanente.", "C", "A extorsão mediante sequestro é crime permanente: dura enquanto a vítima estiver privada da liberdade. Nas infrações permanentes há flagrante enquanto não cessar a permanência (CPP, art. 303).", ""],
  [103, "", 1, "proc", "Prisão preventiva", [44], "A prisão preventiva, admitida nos casos de crimes dolosos punidos com pena privativa de liberdade máxima superior a quatro anos, pode ser decretada em qualquer fase da persecução penal, desde que haja prova da existência do crime e indício suficiente de autoria.", "C", "A preventiva cabe em qualquer fase da investigação ou do processo (CPP, art. 311), se houver prova do crime e indício suficiente de autoria (art. 312), nos crimes dolosos com pena máxima superior a 4 anos (art. 313, I).", "Depois da prova, a Lei 13.964/2019 (Pacote Anticrime) proibiu a decretação da preventiva de ofício pelo juiz (CPP, art. 311) e passou a exigir também perigo gerado pelo estado de liberdade do imputado (art. 312)."],
  [104, "", 1, "proc", "Prisão preventiva", [44], "A legislação processual obsta a decretação da prisão preventiva e temporária no caso de o acusado apresentar-se espontaneamente em juízo ou perante a autoridade policial, prestar declarações acerca dos fatos apurados e entregar o passaporte, assim como no caso de o juiz verificar, pelas provas constantes dos autos, que o agente praticou o fato em estado de necessidade, legítima defesa ou no estrito cumprimento do dever legal.", "E", "A apresentação espontânea não impede a prisão preventiva nem a temporária. Já a preventiva não será decretada se o juiz verificar, pelas provas, que o agente agiu em estado de necessidade, legítima defesa ou estrito cumprimento do dever legal (CPP, art. 314). Só a segunda parte está certa.", ""],
  [105, "", 1, "adm", "Empresas estatais", [45], "Existe a possibilidade de participação de recursos particulares na formação do capital social de empresa pública federal.", "E", "O capital da empresa pública é todo público. Podem participar outras pessoas jurídicas de direito público e entidades da administração indireta, desde que a maioria do capital votante fique com a União (Decreto-Lei 200/1967, art. 5º, II). Recursos particulares, não.", ""],
  [106, "", 1, "adm", "Empresas estatais", [45], "O foro competente para o julgamento de ação de indenização por danos materiais contra empresa pública federal é a justiça federal.", "C", "Pelo art. 109, I, da CF, a justiça federal julga as causas em que empresa pública federal for autora, ré, assistente ou opoente, salvo falência, acidente de trabalho e as da Justiça Eleitoral e do Trabalho.", ""],
  [108, "", 1, "adm", "Licitações", [46], "Configura-se a inexigibilidade de licitação quando a União é obrigada a intervir no domínio econômico para regular preço ou normalizar o abastecimento.", "E", "Intervir no domínio econômico para regular preços ou normalizar o abastecimento era caso de licitação dispensável (Lei 8.666/1993, art. 24, VI), não de inexigibilidade.", "A Lei 8.666/1993 foi substituída pela Lei 14.133/2021, que mantém o caso como dispensa de licitação (art. 75, X)."],
  [109, "", 1, "adm", "Improbidade administrativa", [47], "Se o suposto autor do ato alegar que não tinha conhecimento prévio da ilicitude, o ato de improbidade restará afastado, por ser o desconhecimento da norma motivo para afastá-lo.", "E", "Alegar que não conhecia a norma não afasta, por si só, o ato de improbidade: ninguém se escusa de cumprir a lei alegando que não a conhece. O que importa é o elemento subjetivo da conduta, provado no caso.", "Depois da prova, a Lei 14.230/2021 passou a exigir dolo em todos os atos de improbidade (Lei 8.429/1992, art. 1º, §§ 1º a 3º): não há mais improbidade culposa."],
  [110, "", 1, "con", "Direitos e garantias fundamentais", [48], "O direito ao silêncio, constitucionalmente assegurado ao preso, estende-se a pessoa denunciada ou investigada em qualquer processo criminal, em inquérito policial, em processo administrativo disciplinar e àquela que for convocada a prestar depoimento perante comissão parlamentar de inquérito.", "C", "Para o STF, o direito ao silêncio vale para qualquer pessoa que possa se incriminar: investigados, réus e testemunhas, em processo penal ou administrativo, e também perante CPI.", ""],
  [111, "", 1, "con", "Direitos e garantias fundamentais", [48], "O exercício do direito à liberdade de reunião em locais abertos ao público, previsto na Constituição Federal, condiciona-se a dois requisitos expressos: o encontro não pode frustrar outro anteriormente convocado para o mesmo local e a autoridade competente deve ser previamente avisada a respeito de sua realização.", "C", "Pelo art. 5º, XVI, da CF, a reunião em locais abertos ao público independe de autorização. Exige só que não frustre outra já convocada para o mesmo local e prévio aviso à autoridade competente.", ""],
  [112, "", 1, "con", "Poder Executivo", [49], "Como são irrenunciáveis, todas as atribuições privativas do presidente da República previstas no texto constitucional não podem ser delegadas a outrem.", "E", "O presidente pode delegar as atribuições dos incisos VI, XII e XXV (primeira parte) do art. 84 aos ministros de Estado, ao Procurador-Geral da República ou ao Advogado-Geral da União (parágrafo único). Nem todas são indelegáveis.", ""],
  [113, "", 1, "con", "Segurança pública", [50], "Cabe à Polícia Federal apurar infrações penais que atentem contra os bens, serviços e interesses da administração direta, das autarquias e das fundações públicas da União. Às polícias civis dos estados cabem as funções de polícia judiciária das entidades de direito privado da administração indireta federal.", "E", "Cabe à PF apurar infrações contra bens, serviços e interesses da União, de suas autarquias e de suas empresas públicas (CF, art. 144, § 1º, I). As infrações contra empresas públicas federais são da PF, não das polícias civis.", ""],
  [114, "", 1, "con", "Segurança pública", [50], "A Polícia Federal, as polícias militares e os corpos de bombeiros militares são forças auxiliares e reserva do exército.", "E", "São forças auxiliares e reserva do Exército as polícias militares e os corpos de bombeiros militares (CF, art. 144, § 6º). A Polícia Federal não está nessa lista.", ""],
  [115, "", 1, "especial", "Estrangeiros", [51], "Considere que determinado cidadão australiano deseje vir de férias ao Brasil, por um período de trinta dias, onde pretende ministrar aulas remuneradas de surfe e comercializar aparelhos eletrônicos oriundos da Austrália. Nessa situação, caso não haja acordo internacional entre Brasil e Austrália para a dispensa de visto, o governo brasileiro poderá conceder o visto de turista ao referido cidadão.", "E", "O visto de turista era para quem vinha em caráter recreativo ou de visita, sem intuito de trabalho remunerado (Lei 6.815/1980, art. 9º). Dar aulas pagas e vender produtos afastam esse visto.", "A Lei 6.815/1980 (Estatuto do Estrangeiro) foi revogada pela Lei de Migração (Lei 13.445/2017). O visto de turista virou visto de visita, que também não permite atividade remunerada no Brasil (art. 13, § 1º)."],
  [116, "", 1, "especial", "Lei de Tortura", [51], "O policial condenado por induzir, por meio de tortura praticada nas dependências do distrito policial, um acusado de tráfico de drogas a confessar a prática do crime perderá automaticamente o seu cargo, sendo desnecessário, nessa situação, que o juiz sentenciante motive a perda do cargo.", "C", "Na Lei 9.455/1997, a condenação acarreta a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena (art. 1º, § 5º). Para o STJ, esse efeito é automático e dispensa motivação específica na sentença.", ""],
  [117, "", 1, "especial", "Segurança privada", [51], "Ainda que se instale em cidade interiorana e apresente reduzida circulação financeira, a cooperativa singular de crédito estará obrigada a contratar vigilantes, independentemente de se provar que a contratação inviabilizará economicamente a manutenção do estabelecimento.", "E", "A Lei 7.102/1983 permitia dispensar a contratação de vigilantes nas cooperativas singulares de crédito de reduzida circulação financeira quando isso inviabilizasse economicamente o estabelecimento (art. 1º, § 2º, III).", "Depois da prova, a Lei 7.102/1983 foi substituída pelo Estatuto da Segurança Privada (Lei 14.967/2024), que regula de novo a segurança das instituições financeiras."],
  [119, "", 1, "especial", "Crimes ambientais", [52], "Se o rebanho bovino de determinada propriedade rural estiver sendo constantemente atacado por uma onça, o dono dessa propriedade, para proteger o rebanho, poderá, independentemente de autorização do poder público, abater o referido animal silvestre.", "E", "Não é crime abater animal para proteger lavouras, pomares e rebanhos da ação predatória, desde que legal e expressamente autorizado pela autoridade competente (Lei 9.605/1998, art. 37, II). Sem autorização, o abate é crime.", ""],
  [120, "", 1, "especial", "Estatuto do Desarmamento", [52], "Responderá pelo delito de omissão de cautela o proprietário ou o diretor responsável de empresa de segurança e transporte de valores que deixar de registrar ocorrência policial e de comunicar à Polícia Federal, nas primeiras vinte e quatro horas depois de ocorrido o fato, a perda de munição que esteja sob sua guarda.", "C", "O parágrafo único do art. 13 da Lei 10.826/2003 pune com as penas da omissão de cautela o dono ou diretor de empresa de segurança e transporte de valores que não registra ocorrência e não comunica à PF, em 24 horas, a perda, o furto ou o roubo de arma, acessório ou munição sob sua guarda.", ""],
];
